import { Application, Assets, Container, Graphics, Sprite, Texture, Rectangle } from './pixi.js';
import { STAGES, PHYSICS, CAR_SIZE, CAR_VISUAL_SCALE, DRIFT_MARK_LIFE } from './config.js';
import { STAGE_PATHS } from './track/stages.js';
import { buildSurface, surfaceExtent, buildRampStructure, buildTunnelStructure, buildElevatedRoadOverlay, buildElevatedDeckShadow, elevatedRuns } from './render/surfaces.js';
import { buildProps, buildGroundPatches, buildSideStreets } from './render/props.js';
import { buildMiniMap } from './render/minimap.js';
import { buildFinishFX } from './render/finishfx.js';
import { buildBoostFlame } from './render/boostfx.js';
import { LAYOUTS } from './track/layouts.js';
import { PlayerCar } from './game/player.js';
import { RivalCar } from './game/rival.js';
import { Race, resolveContacts, autoDrivePostRace } from './game/race.js';

const BASE_PLAYER_PHYSICS = { ...PHYSICS };

const TEXTURES = {
  road_asphalt: "data:image/png;base64,",
  grass: "data:image/png;base64,",
  grass_dry: "data:image/png;base64,",
  dirt: "data:image/png;base64,",
  gravel: "data:image/png;base64,",
  curb_redwhite: "data:image/png;base64,",
  curb_concrete: "data:image/png;base64,",
  rut_overlay: "data:image/png;base64,",
  edge_shadow: "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAEAAAAAICAYAAABJYvnfAAAASklEQVR4nOWOMQ6AMAwDD495Oz+GUtZQWWLs4JOss5UlR1WdwAXczS7D9O6/PMZr75mmd0+zWW4YfxDhiHBEOCIcEY4IR7sf2M0LLAY3Lq/zwyYAAAAASUVORK5CYII=",
  dash_white: "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAACACAYAAAAClekiAAAAgElEQVR4nO3XMQ3DUBAE0fmrUAgR88dgCAGS5iL5FwawVeSZ/rZ43a2ZoekFHA8fWDPzbQemGUhz7MAulMUBNEADNNBgF8riABqgARpocH8sH8qB878H1sy82wGaUl07cBXK4gAaoAEaaLALZXEADdAADTTYhbI4gAZogAYacPUDFzYWG2ug4pUAAAAASUVORK5CYII=",
  dash_yellow: "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAACACAYAAAAClekiAAAAd0lEQVR4nO3XMRGEABAEwWELDL0OjJMgAQNkKPgqLkDApjP5bdDZLc+x07QCPweoDbZmIM2xA1MoiwNogAZooMEUyuIAGqABGmjw/QsX5cDpAHdjkObYgSmUxQE0QAM00GAKZXEADdAADTSYQlkcQAM0QAMNePsD8rUJHw/mNZkAAAAASUVORK5CYII=",
  shadow_blob: "data:image/png;base64,",
  checker: "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAIAAAAAgCAYAAADaInAlAAAAjElEQVR4nO3asQ3EIBAAQfxFkNN/UVRB7C+CyNqZ/ISEViTcc855x4W11s342HtfzTt/Xd3f72qazxNAnADiBBAngDgBxAkgTgBxAogTQJwA4gQQJ4A4AcQJIO6Zc17tA/jP35/eZ/ACxAkgTgBxAogTQJwA4gQQJ4A4AcQJIE4AcQKIE0CcAOIEMNr+qwUaXpYGH2gAAAAASUVORK5CYII=",
  patch_dirt: "data:image/png;base64,",
  patch_dry: "data:image/png;base64,",
  patch_dark: "data:image/png;base64,",
};

const CARS = {
  player: "data:image/png;base64,",
  devilz: "data:image/png;base64,",
  ae86: "data:image/png;base64,",
  prius: "data:image/png;base64,",
};

const PROP_ATLAS = "data:application/json;base64,";

const SURFACE_PRESET_BY_STAGE = { 1: 'circuit', 2: 'city', 3: 'mountain', 4: 'highway', 5: 'grandtour' };

/** Textures used as tiling materials must wrap; atlas frames never can. */
const WRAPPED = [
  'road_asphalt', 'grass', 'grass_dry', 'dirt', 'gravel',
  'curb_redwhite', 'curb_concrete', 'rut_overlay', 'edge_shadow',
  'dash_white', 'dash_yellow', 'checker',
];

export class Game {
  constructor(app, tex, cars, propSheet) {
    this.app = app;
    this.tex = tex;
    this.cars = cars;
    this.propSheet = propSheet;

    this.world = new Container();
    this.world.label = 'world';
    app.stage.addChild(this.world);

    this.input = { left: false, right: false, brake: false };
    // Three camera distances. Level 0 is the existing/current framing
    // (closest); levels 1 and 2 progressively pull the camera back.
    this.baseZoom = Math.max(0.28, Math.min(0.42, app.screen.width / 1080));
    this.zoomLevels = [1.00, 1.15, 1.30];
    this.zoomLevel = 0;
    this.zoom = this.baseZoom * this.zoomLevels[this.zoomLevel];
    this.stageId = null;

    this.finishFX = buildFinishFX();
    app.stage.addChild(this.finishFX.view);
    this._prevRaceState = null;
  }

  cycleZoom() {
    this.zoomLevel = (this.zoomLevel + 1) % this.zoomLevels.length;
    this.zoom = this.baseZoom * this.zoomLevels[this.zoomLevel];
    return this.zoomLevel;
  }

  loadStage(stageId) {
    const cfg = STAGES[stageId];
    // Restore the original/default handling first, then apply only the
    // selected stage's explicit player tuning. This prevents Stage 3's
    // drift/steering work from leaking into Stage 1.
    Object.assign(PHYSICS, BASE_PLAYER_PHYSICS, cfg.playerPhysics || {});
    const path = (STAGE_PATHS[stageId] || STAGE_PATHS[1])();

    this.world.removeChildren();
    if (this.miniMap) { this.app.stage.removeChild(this.miniMap.view); this.miniMap = null; }
    this.finishFX.reset();
    this._prevRaceState = null;
    this.stageId = stageId;
    this.path = path;
    this.cfg = cfg;

    const preset = SURFACE_PRESET_BY_STAGE[stageId] || 'circuit';



    this.world.addChild(buildSurface(path, this.tex, {
      roadHalf: cfg.roadHalf,
      wallHalf: cfg.wallHalf,
      preset,
    }));

    // Tunnel: darkens/walls/lights whatever stretch of route the stage
    // marks with setTunnelRange(). Drawn against the ground surface, before
    // anything elevated, since a tunnel is cut into the level it sits on.
    // No-ops on any stage that marks none.
    this.world.addChild(buildTunnelStructure(path, { roadHalf: cfg.roadHalf, wallHalf: cfg.wallHalf }));

    // --- grade separation, by layer order ---
    // buildSurface() above laid the WHOLE route down in one set of full-loop
    // ribbons, so where stage 4's course crosses over itself both passes are
    // in the same meshes and neither is reliably on top. These two passes
    // resolve it: the raised road is re-laid over the ground one, then the
    // deck's own structure (walls, fascia, piers, cast shadow) frames it.
    // Both no-op on a stage whose route never leaves zLevel 0.
    this.world.addChild(buildElevatedDeckShadow(path, { roadHalf: cfg.roadHalf }));
    this.elevatedDeck = buildElevatedRoadOverlay(path, this.tex, {
      roadHalf: cfg.roadHalf,
      preset,
    });
    this.world.addChild(this.elevatedDeck);
    this.world.addChild(buildRampStructure(path, { wallHalf: cfg.wallHalf }));

    // Grid of just the elevated points, so update() can ask "is the player
    // underneath the deck right now" in O(1). A top-down camera has no way
    // to show one road passing under another: the deck is opaque, so at the
    // crossing it would simply cover the car, and the player loses the car
    // they are steering. Fading the deck road (its shadow and its walls stay
    // put, so the bridge keeps its outline) is what makes "I am under it"
    // legible. See the fade in update().
    this._deckGrid = null;
    if (elevatedRuns(path).length) {
      const cell = 400;
      const grid = new Map();
      for (let i = 0; i < path.count; i++) {
        if (path.zLevels[i] < 2) continue;
        const q = path.points[i];
        const k = `${Math.floor(q[0] / cell)},${Math.floor(q[1] / cell)}`;
        let b = grid.get(k);
        if (!b) grid.set(k, (b = []));
        b.push(i);
      }
      this._deckGrid = { grid, cell, reach: cfg.roadHalf + 70 };
    }

    // (The old stage-4 pass here painted a decorative overpass at a fixed
    // fraction of the route -- a bridge-shaped picture beside the road,
    // deliberately not registered with nearest()/collision/AI, because the
    // route of the day never actually crossed itself. The course now has a
    // real grade separation that the player and rival both drive, handled by
    // the deck metadata and the layer order above, so the stand-in is gone.
    // buildVisualHighwayDeck is kept in render/surfaces.js for future
    // scenery that genuinely isn't part of the route.)

    const layout = LAYOUTS[stageId] || null;
    const edge = surfaceExtent(cfg.roadHalf, preset);

    if (layout?.sideStreets?.length) {
      this.world.addChild(buildSideStreets(path, { edge, list: layout.sideStreets }));
    }

    if (layout?.patches) {
      this.world.addChild(buildGroundPatches(path, this.tex, {
        edge, seed: stageId,
        count: layout.patches.count,
        names: layout.patches.textures,
      }));
    }

    // Car sizes are authored in SCREEN pixels (carried over from the Canvas
    // build, where cars were drawn unscaled over a scaled world). Convert to
    // world units so the car keeps the same size relative to the road; this
    // is also the size collision, start-grid spacing, and any decoration
    // meant to match car size (parked ambulance/tow-truck props) must use,
    // since that is the size the car actually occupies once placed in the world.
    const s = 1 / this.zoom;
    this.worldScale = s;

    const props = buildProps(path, this.propSheet, this.tex.shadow_blob, {
      edge, preset, seed: stageId, layout, worldScale: s, wallHalf: cfg.wallHalf,
    });
    this.world.addChild(props.layer);

    // Off-screen props are the cheapest draw load to remove: Stage 4 places
    // 269 of them (two sprites plus, for lights, a glow Graphics each) over
    // an 89,825-unit lap, and only a handful are ever in shot. Pixi has no
    // culling on by default, so every one of them was being transformed and
    // submitted every frame. Flattened to a plain array here because the
    // check runs per prop per frame.
    this._propCull = props.layer.children.map((c) => ({
      node: c, x: c.position.x, y: c.position.y, r: c.cullRadius || 0,
    }));

    // actors sit above the surface
    this.actors = new Container();
    this.actors.label = 'actors';
    this.world.addChild(this.actors);

    const rivalSize = CAR_SIZE[cfg.rival.sprite] || CAR_SIZE.devilz;
    this.rivalSize = rivalSize;
    const playerWorldSize = { w: CAR_SIZE.player.w * s, h: CAR_SIZE.player.h * s };
    const rivalWorldSize = { w: rivalSize.w * s, h: rivalSize.h * s };
    // Cosmetic-only correction (see CAR_VISUAL_SCALE) -- deliberately kept
    // separate from rivalWorldSize/rivalSize, which still drive start-grid
    // spacing and the collision hull, so this never touches gameplay feel.
    const rivalVisualScale = CAR_VISUAL_SCALE[cfg.rival.sprite] ?? { w: 1, h: 1 };
    const rivalDrawSize = { w: rivalWorldSize.w * rivalVisualScale.w, h: rivalWorldSize.h * rivalVisualScale.h };

    // Side-by-side start grid: half of each car's world-space width, plus a
    // clear margin, so they never spawn overlapping regardless of zoom. Cars
    // line up behind the start/finish line, not on top of it (reference
    // build's startPose(back, lateral), back=360).
    const gridMargin = 30;
    const startBack = 360;
    const playerStartLateral = playerWorldSize.w / 2 + gridMargin;
    const rivalStartLateral = -(rivalWorldSize.w / 2 + gridMargin);

    // Drift tire marks + smoke sit at road level, under every shadow/car/flame
    // below -- adding this first keeps it bottom-most in the actors stack.
    this.driftGfx = new Graphics();
    this.actors.addChild(this.driftGfx);

    this.player = new PlayerCar(path, cfg);
    this.player.placeAtStart(-startBack, playerStartLateral);
    this.player.deckId = 0;
    this.player.zLevel = 0;

    this.playerShadow = new Sprite(this.tex.shadow_blob);
    this.playerShadow.anchor.set(0.5);
    this.playerShadow.width = CAR_SIZE.player.w * 1.8 * s;
    this.playerShadow.height = CAR_SIZE.player.h * 1.4 * s;
    this.playerShadow.alpha = 0.5;
    this.actors.addChild(this.playerShadow);

    // Boost exhaust flame, above the shadow but still behind the car body.
    this.boostFlame = buildBoostFlame();
    this.actors.addChild(this.boostFlame.view);

    this.playerSprite = new Sprite(this.cars.player);
    this.playerSprite.anchor.set(0.5);
    this.playerSprite.width = playerWorldSize.w;
    this.playerSprite.height = playerWorldSize.h;
    this.actors.addChild(this.playerSprite);

    // --- rival ---
    this.rival = new RivalCar(path, cfg, cfg.rival);
    this.rival.placeAtStart(-startBack, rivalStartLateral);
    this.rival.deckId = 0;
    this.rival.zLevel = 0;

    this.rivalShadow = new Sprite(this.tex.shadow_blob);
    this.rivalShadow.anchor.set(0.5);
    this.rivalShadow.width = rivalSize.w * 1.8 * s * rivalVisualScale.w;
    this.rivalShadow.height = rivalSize.h * 1.4 * s * rivalVisualScale.h;
    this.rivalShadow.alpha = 0.5;
    this.actors.addChild(this.rivalShadow);

    // Same effect as the player's, its own instance -- built once here so
    // it works on every stage, not just the one this was added for.
    this.rivalBoostFlame = buildBoostFlame();
    this.actors.addChild(this.rivalBoostFlame.view);

    this.rivalSprite = new Sprite(this.cars[cfg.rival.sprite] || this.cars.devilz);
    this.rivalSprite.anchor.set(0.5);
    this.rivalSprite.width = rivalDrawSize.w;
    this.rivalSprite.height = rivalDrawSize.h;
    if (cfg.rival.tint) this.rivalSprite.tint = cfg.rival.tint;
    this.actors.addChild(this.rivalSprite);

    // Deck state has to be right from the grid, not only once the lights go
    // out: update() only syncs it while racing, so without this both cars
    // would sit on whatever deck they were last left on through the VS card
    // and the countdown.
    this.syncDeck(this.player);
    this.syncDeck(this.rival);

    // --- race progression ---
    // startBack keeps lap/finish thresholds aligned with the painted line
    // instead of the grid position the cars actually start from.
    this.race = new Race(path, { startBack });
    this.playerEntry = this.race.addCar(this.player, { isPlayer: true, name: 'YOU' });
    this.rivalEntry = this.race.addCar(this.rival, { isPlayer: false, name: cfg.rivalName });

    this.miniMap = buildMiniMap(path, cfg);
    this.app.stage.addChild(this.miniMap.view);
    // re-adding an existing child moves it to the top of the stage's list,
    // so the celebration always draws over the minimap
    this.app.stage.addChild(this.finishFX.view);

    return { path, cfg };
  }

  /**
   * Read a car's deck/zLevel from the route position it is already tracking.
   * Cars that keep no hint (anything driven by something other than their own
   * update()) fall back to a global lookup.
   */
  syncDeck(car) {
    const idx = car._routeHint ?? this.path.nearest(car.x, car.y).index;
    const layer = this.path.layerAtIndex(idx);
    car.deckId = layer.deckId;
    car.zLevel = layer.zLevel;
  }

  update(dt) {
    const state = this.race.state;
    const p = this.player;

    if (state === 'racing') {
      p.update(dt, this.input);

      // Which deck each car is on, read straight off the route hint the car
      // already maintains. That hint IS the car's position on the route --
      // the same lookup that decides its wall, its off-road test and its
      // racing line -- so taking the deck from it keeps "which road am I on"
      // and "which deck am I on" in agreement by construction.
      //
      // These used to be two independent hints (a separate _layerHintIndex,
      // re-derived with its own local search). On a course that never
      // actually crossed itself they always agreed; on one that does they
      // can drift apart at the crossing, and then a car can be driving the
      // ground road while being treated as on the bridge -- i.e. passing
      // through the other car instead of hitting it.
      this.syncDeck(p);
      this.rival.update(dt, {
        lap: this.rivalEntry.progress.lap, totalLaps: this.race.totalLaps,
        player: p, gap: this.rivalEntry.progress.total - this.playerEntry.progress.total,
      });
      // Same for the rival: same route, same rule, so two cars on the same
      // physical stretch always agree about whether they can touch.
      this.syncDeck(this.rival);
      // Hull sizes must be in WORLD units (screen size * 1/zoom), matching
      // how the sprites are actually scaled -- passing the raw screen-pixel
      // CAR_SIZE here made every hull ~2.5x too small, so cars could drive
      // through each other almost completely before contact registered.
      // Cars on stacked road decks must not physically collide through the bridge.
      // Current Stage4 starts both racers on deck 0; future ramps will switch this.
      if ((p.deckId ?? 0) === (this.rival.deckId ?? 0)) {
        resolveContacts(
          [p, this.rival],
          [
            { w: CAR_SIZE.player.w * this.worldScale, h: CAR_SIZE.player.h * this.worldScale },
            { w: this.rivalSize.w * this.worldScale, h: this.rivalSize.h * this.worldScale },
          ],
        );
      }
    } else if (state === 'finished') {
      // Race is over: clear any remaining drift state/visual yaw for BOTH cars,
      // then keep them circulating under AI control. This prevents a car from
      // staying visually sideways forever if it crosses the line mid-drift.
      p.boosting = false;
      p.boostTimer = 0;

      p.drifting = false;
      p.driftSign = 0;
      p.driftSlipAngle = 0;
      p.driftVisualAngle += (0 - p.driftVisualAngle) * (1 - Math.exp(-dt * 12.0));

      this.rival.drifting = false;
      this.rival._driftAmt = 0;
      this.rival.driftVisualAngle += (0 - this.rival.driftVisualAngle) * (1 - Math.exp(-dt * 12.0));

      // After the finish, keep the two cars on separate sides of the road
      // so they don't converge onto the same centreline and overlap.
      autoDrivePostRace(p, this.path, dt, 410, -52);
      autoDrivePostRace(this.rival, this.path, dt, 390, 52);
    }
    this.race.update(dt);

    // Fade the elevated deck road while the player is underneath it, so the
    // car stays visible where the course crosses over itself. Only the deck
    // ROAD fades -- its cast shadow and its walls/fascia/piers are separate
    // layers and stay put, so the bridge keeps a clear outline overhead
    // instead of vanishing. Eased rather than switched, otherwise the whole
    // bridge pops the instant the car's nose reaches its edge.
    if (this._deckGrid && this.elevatedDeck) {
      const { grid, cell, reach } = this._deckGrid;
      let under = false;
      if ((p.zLevel ?? 0) < 2) {
        const gx = Math.floor(p.x / cell), gy = Math.floor(p.y / cell);
        const r2 = reach * reach;
        for (let dy = -1; dy <= 1 && !under; dy++) {
          for (let dx = -1; dx <= 1 && !under; dx++) {
            const bucket = grid.get(`${gx + dx},${gy + dy}`);
            if (!bucket) continue;
            for (const i of bucket) {
              const q = this.path.points[i];
              if ((q[0] - p.x) ** 2 + (q[1] - p.y) ** 2 < r2) { under = true; break; }
            }
          }
        }
      }
      const target = under ? 0.42 : 1;
      this.elevatedDeck.alpha += (target - this.elevatedDeck.alpha) * (1 - Math.exp(-dt * 9));
    }

    // race.update() can flip state to 'finished' just now (checked fresh,
    // since the `state` captured above is from before that call ran)
    if (this.race.state === 'finished' && this._prevRaceState !== 'finished') {
      // Crossing the line cancels drift immediately, but DO NOT snap the
      // chassis angle to the track tangent. Post-race auto drive will
      // straighten it quickly and continuously over the following frames.
      for (const car of [p, this.rival]) {
        car.drifting = false;
        if ('driftSlipAngle' in car) car.driftSlipAngle = 0;
        if ('driftSign' in car) car.driftSign = 0;
        if ('_driftAmt' in car) car._driftAmt = 0;
      }

      const place = this.race.positionOf(this.playerEntry);
      this.finishFX.trigger(place, this.app.screen.width, this.app.screen.height);
    }
    this._prevRaceState = this.race.state;

    // sprite points "up" in its art, so rotate by +90°. The camera below
    // rotates the world by -(p.angle + 90°), which cancels p.angle out of
    // the player's own screen rotation entirely -- necessary so the car
    // always faces up-screen, but it also means p.angle alone can never
    // make the sprite visibly tilt. Adding driftVisualAngle on top (which
    // the camera transform doesn't know about) is what actually shows up
    // as a tilt on screen while drifting.
    this.playerSprite.position.set(p.x, p.y);
    this.playerSprite.rotation = p.angle + Math.PI / 2 + p.driftVisualAngle;
    this.playerShadow.position.set(p.x + 6, p.y + 8);
    this.playerShadow.rotation = this.playerSprite.rotation;

    this.rivalSprite.position.set(this.rival.x, this.rival.y);
    this.rivalSprite.rotation = this.rival.angle + Math.PI / 2 + (this.rival.driftVisualAngle || 0);
    this.rivalShadow.position.set(this.rival.x + 6, this.rival.y + 8);
    this.rivalShadow.rotation = this.rivalSprite.rotation;

    // camera: player pinned to a fixed screen anchor, world rotated so the
    // car always points up the screen
    const shakeX = p.shake ? (Math.random() - 0.5) * p.shake : 0;
    const shakeY = p.shake ? (Math.random() - 0.5) * p.shake : 0;
    const { width: W, height: H } = this.app.screen;
    this.world.pivot.set(p.x, p.y);
    this.world.position.set(W / 2 + shakeX, H * 0.62 + shakeY);
    this.world.rotation = -(p.angle + Math.PI / 2);
    this.world.scale.set(this.zoom);

    this.cullProps(p.x, p.y, W, H);
    this.miniMap.update(W, p, this.rival);
    this.updateDriftFX();
    this.boostFlame.update(p, this.worldScale);
    this.rivalBoostFlame.update(this.rival, this.worldScale);
    this.finishFX.update(dt, W, H);
  }

  /**
   * Hide props that cannot be on screen this frame.
   *
   * The camera rotates with the car, so a screen rectangle is not an
   * axis-aligned box in world space. Rather than transform each prop, the
   * test is a radius about the pivot (the player), which is exactly
   * rotation-invariant: the furthest the view can reach from the pivot is
   * the distance to the most distant screen corner, converted to world
   * units. Cheap (one squared distance per prop) and never wrong, at the
   * cost of keeping a few props alive just outside the corners.
   */
  cullProps(px, py, W, H) {
    if (!this._propCull) return;
    // pivot sits at (W/2, H*0.62) on screen -- the long reach is upward
    const reach = Math.hypot(W / 2, H * 0.62) / this.zoom;
    for (let i = 0; i < this._propCull.length; i++) {
      const c = this._propCull[i];
      const lim = reach + c.r;
      const ox = c.x - px, oy = c.y - py;
      const vis = ox * ox + oy * oy <= lim * lim;
      if (c.node.visible !== vis) c.node.visible = vis;
    }
  }

  /**
   * Tire marks + smoke while the player drifts -- ported from the reference
   * build's drawDriftFX. Drawn directly in world space (unlike that build,
   * which projected world points to screen manually every frame): adding
   * this Graphics to `actors` lets Pixi's own camera transform handle that.
   */
  updateDriftFX() {
    const g = this.driftGfx;
    g.clear();
    const s = this.worldScale;
    this.drawDriftTrail(g, this.player, CAR_SIZE.player.w, s);
    // narrower stroke for the 86 specifically (by request) -- tyre spacing
    // (off) still tracks its real body width, only the mark's own thickness
    // is scaled down, so the twin lines don't end up misaligned with the
    // rear tyres.
    this.drawDriftTrail(g, this.rival, this.rivalSize.w, s, 0.6);
  }

  /** Shared by player and rival -- same tyre-mark-plus-smoke look for both,
   *  just keyed off each car's own driftTrail/drifting/body width.
   *  `markWidthScale` narrows/widens the stroke only, independent of the
   *  tyre-spacing offset. */
  drawDriftTrail(g, car, bodyWidth, s, markWidthScale = 1) {
    const trail = car.driftTrail;

    for (let i = 1; i < trail.length; i++) {
      const a = trail[i - 1], b = trail[i];
      const alpha = Math.max(0, Math.min(1, b.life / DRIFT_MARK_LIFE)) * 0.42;
      if (alpha <= 0) continue;

      const dx = b.x - a.x, dy = b.y - a.y;
      const len = Math.hypot(dx, dy) || 1;
      const nx = -dy / len, ny = dx / len;
      // twin marks track the rear tyres, so their spacing should follow the
      // car's own tyre position rather than a fixed constant unrelated to it
      // (measured from the sprite: rear tyres sit ~0.26x the body width out
      // from the centreline; nudged a little tighter again by request)
      const off = bodyWidth * 0.22 * s;
      const width = bodyWidth * 0.065 * s * markWidthScale;

      g.moveTo(a.x + nx * off, a.y + ny * off).lineTo(b.x + nx * off, b.y + ny * off)
        .stroke({ width, color: 0x141414, alpha });
      g.moveTo(a.x - nx * off, a.y - ny * off).lineTo(b.x - nx * off, b.y - ny * off)
        .stroke({ width, color: 0x141414, alpha });
    }

    if (car.drifting && trail.length) {
      const p = trail[trail.length - 1];
      for (let i = 0; i < 3; i++) {
        const ox = (Math.random() - 0.5) * 18 * s;
        const oy = (8 + Math.random() * 18) * s;
        const r = (4 + Math.random() * 5) * s;
        g.circle(p.x + ox, p.y + oy, r).fill({ color: 0xe9edf0, alpha: 0.17 });
      }
    }
  }
}

export async function boot({ stageId = 1, onReady } = {}) {
  const app = new Application();
  await app.init({
    background: '#161a1e',
    resizeTo: window,
    antialias: true,
    resolution: Math.min(2, window.devicePixelRatio || 1),
    autoDensity: true,
    preference: 'webgl',
  });
  document.getElementById('app').appendChild(app.canvas);

  const urls = [...Object.values(TEXTURES), ...Object.values(CARS), PROP_ATLAS];
  const loaded = await Assets.load(urls);

  const tex = {};
  for (const [k, url] of Object.entries(TEXTURES)) tex[k] = loaded[url];
  const cars = {};
  for (const [k, url] of Object.entries(CARS)) cars[k] = loaded[url];
  // data: JSON URLs are not automatically promoted to a Pixi Spritesheet
  // in every mobile browser. Build the atlas textures explicitly so the
  // standalone HTML behaves the same as the folder build.
  const atlasData = await (await fetch(PROP_ATLAS)).json();
  const atlasTexture = await Assets.load(atlasData.meta.image);
  const propTextures = {};
  for (const [name, entry] of Object.entries(atlasData.frames || {})) {
    const f = entry.frame;
    propTextures[name] = new Texture({
      source: atlasTexture.source,
      frame: new Rectangle(f.x, f.y, f.w, f.h),
    });
  }
  const propSheet = { textures: propTextures };

  for (const k of WRAPPED) tex[k].source.addressMode = 'repeat';

  // Car art is drawn from large source photos (the rival roster is well
  // over 700px on a side) down to a car's actual ~50-90px on-screen size --
  // a >10x minification. Without mipmaps, GPU bilinear sampling at that
  // ratio can blend a texel's opaque colour with a same-sample-footprint
  // *transparent* neighbour (exactly what happens at a car's thin
  // silhouette details -- tyres, mirrors) and come out partially see-
  // through, which barely reads against dark asphalt but is obvious over
  // a bright crosswalk or kerb line. Mipmapping fixes the sampling, not
  // just antialiasing quality.
  for (const k of Object.keys(CARS)) {
    const src = cars[k].source;
    src.mipmap = 'on';
    // `mipmap` alone is just the policy flag -- PixiJS only actually
    // generates the mip chain when this is also on, otherwise it's sampled
    // as if mipmap were 'off' regardless of the setting above.
    src.autoGenerateMipmaps = true;
    src.update();
  }

  const game = new Game(app, tex, cars, propSheet);
  game.loadStage(stageId);

  app.ticker.add((ticker) => {
    game.update(Math.min(0.033, ticker.deltaMS / 1000));
  });

  onReady?.(game, app);
  return { game, app };
}
